#if canImport(AppKit)
import AppKit
import PassthroughCore

/// The Mac's clipboard as clipboard sync sees it: what may go to the other
/// side, and how what came from it is put there.
public enum MacClipboard {
    /// Marks what this side put there from the stream, so it isn't sent back.
    public static let synced = NSPasteboard.PasteboardType("dev.dpatel.passthrough.synced")
    /// Contents never synced: passwords and one-time codes (Concealed), what an app
    /// says is fleeting or made up (Transient, AutoGenerated), the iPhone's
    /// Universal Clipboard, a phone's paste (Transient), and what came from the stream.
    static let neverSynced: [NSPasteboard.PasteboardType] = [
        .init("org.nspasteboard.ConcealedType"), .init("org.nspasteboard.TransientType"),
        .init("org.nspasteboard.AutoGeneratedType"), .init("com.apple.is-remote-clipboard"), synced,
    ]

    public enum Snapshot: Sendable {
        case payload(ClipPayload)
        /// Over the clipboard's limits: files over 500 MB in all (drag them in instead), or text or an image over its own.
        case tooLarge(files: Bool)
        /// Nothing that syncs (empty, secret, or from the stream).
        case nothing
    }

    /// Whether the clipboard's types say it may sync. Cheap: types only.
    public static func maySync(_ types: [NSPasteboard.PasteboardType]?) -> Bool {
        guard let types, !types.isEmpty else { return false }
        return !types.contains(where: neverSynced.contains)
    }

    /// What's on the clipboard to send. May block: an app that provides its data
    /// lazily is asked for it, so call it off the main thread.
    public static func snapshot(_ pasteboard: NSPasteboard = .general) -> Snapshot {
        // The types are looked at once and the contents read after: if the clipboard changed in
        // between (a password manager copying meanwhile), what was read isn't what was checked.
        let count = pasteboard.changeCount
        let snapshot = read(pasteboard)
        return pasteboard.changeCount == count ? snapshot : .nothing
    }

    private static func read(_ pasteboard: NSPasteboard) -> Snapshot {
        guard maySync(pasteboard.types) else { return .nothing }
        let urls = (pasteboard.readObjects(forClasses: [NSURL.self], options: [.urlReadingFileURLsOnly: true]) as? [URL]) ?? []
        if !urls.isEmpty {
            switch ClipPayload.files(urls, maxBytes: ClipSyncWire.maxClipboardFiles, maxItems: ClipSyncWire.maxItems) {
            case let .success(payload): return payload.items.isEmpty ? .nothing : .payload(payload)
            case .failure(.tooLarge): return .tooLarge(files: true)
            case .failure: return .nothing
            }
        }
        var items: [ClipPayload.Item] = []
        var over = false
        func add(_ format: ClipSyncWire.Format, _ data: Data?, cap: UInt64) {
            guard let data, !data.isEmpty else { return }
            guard UInt64(data.count) <= cap else { over = true; return }
            items.append(.data(format, data))
        }
        add(.text, pasteboard.string(forType: .string).map { Data($0.utf8) }, cap: ClipSyncWire.maxClipboardText)
        add(.rtf, pasteboard.data(forType: .rtf), cap: ClipSyncWire.maxClipboardText)
        add(.html, pasteboard.data(forType: .html), cap: ClipSyncWire.maxClipboardText)
        add(.png, png(pasteboard), cap: ClipSyncWire.maxClipboardImage)
        if items.isEmpty { return over ? .tooLarge(files: false) : .nothing }
        return .payload(ClipPayload(items: items))
    }

    /// The clipboard's image as PNG: its own PNG, or its TIFF converted.
    private static func png(_ pasteboard: NSPasteboard) -> Data? {
        if let png = pasteboard.data(forType: .png) { return png }
        guard let tiff = pasteboard.data(forType: .tiff), let rep = NSBitmapImageRep(data: tiff) else { return nil }
        return rep.representation(using: .png, properties: [:])
    }

    /// The folders directly under `staging` that the clipboard's files are in now, standardized.
    public static func folders(within staging: URL, _ pasteboard: NSPasteboard = .general) -> Set<URL> {
        let urls = (pasteboard.readObjects(forClasses: [NSURL.self], options: [.urlReadingFileURLsOnly: true]) as? [URL]) ?? []
        let base = staging.standardizedFileURL.pathComponents
        return Set(urls.compactMap { url -> URL? in
            let parts = url.standardizedFileURL.pathComponents
            guard parts.count > base.count, Array(parts.prefix(base.count)) == base else { return nil }
            return staging.appendingPathComponent(parts[base.count], isDirectory: true).standardizedFileURL
        })
    }

    /// Puts what came from the other side on the clipboard, marked as from the
    /// stream; returns the clipboard's change count after.
    @discardableResult
    public static func write(_ transfer: ReceivedTransfer, to pasteboard: NSPasteboard = .general) -> Int {
        var items: [NSPasteboardItem] = []
        let files = transfer.topLevel
        if !files.isEmpty {
            for url in files {
                let item = NSPasteboardItem()
                item.setString(url.absoluteString, forType: .fileURL)
                items.append(item)
            }
        } else {
            let item = NSPasteboardItem()
            if let text = transfer.data(.text).flatMap({ String(data: $0, encoding: .utf8) }) { item.setString(text, forType: .string) }
            if let rtf = transfer.data(.rtf) { item.setData(rtf, forType: .rtf) }
            if let html = transfer.data(.html) { item.setData(html, forType: .html) }
            if let png = transfer.data(.png) { item.setData(png, forType: .png) }
            items.append(item)
        }
        items.first?.setData(Data(), forType: synced)
        // This Mac's only: not on to Universal Clipboard and the owner's other devices, as Windows keeps it off its cloud clipboard.
        pasteboard.prepareForNewContents(with: .currentHostOnly)
        pasteboard.writeObjects(items)
        return pasteboard.changeCount
    }
}

/// Watches the Mac's clipboard while anyone syncs it, and tells each of them
/// about a change that may sync (on the main thread). macOS has no
/// notification for it, so the change count is looked at a few times a second.
@MainActor
public final class ClipboardWatcher {
    public static let shared = ClipboardWatcher()

    private var watchers: [UUID: (MacClipboard.Snapshot) -> Void] = [:]
    private var timer: Timer?
    private var lastCount = NSPasteboard.general.changeCount
    private var reading = false
    private var changedWhileReading = false
    private let readQueue = DispatchQueue(label: "passthrough.clipsync.pasteboard", qos: .userInitiated)

    static let interval: TimeInterval = 0.3

    public func watch(_ onChange: @escaping (MacClipboard.Snapshot) -> Void) -> UUID {
        let id = UUID()
        watchers[id] = onChange
        if timer == nil {
            lastCount = NSPasteboard.general.changeCount
            let timer = Timer(timeInterval: Self.interval, repeats: true) { _ in
                MainActor.assumeIsolated { ClipboardWatcher.shared.tick() }
            }
            RunLoop.main.add(timer, forMode: .common)
            self.timer = timer
        }
        return id
    }

    public func unwatch(_ id: UUID) {
        watchers[id] = nil
        if watchers.isEmpty {
            timer?.invalidate()
            timer = nil
        }
    }

    /// What this side just wrote isn't a change to send.
    public func wrote(changeCount: Int) { lastCount = changeCount }

    /// The clipboard as it is now, read off the main thread.
    public func current(_ done: @escaping @MainActor (MacClipboard.Snapshot) -> Void) {
        readQueue.async {
            let snapshot = MacClipboard.snapshot()
            DispatchQueue.main.async { done(snapshot) }
        }
    }

    private func tick() {
        let count = NSPasteboard.general.changeCount
        guard count != lastCount else { return }
        lastCount = count
        guard !reading else { changedWhileReading = true; return }
        guard MacClipboard.maySync(NSPasteboard.general.types) else { return }
        reading = true
        current { [weak self] snapshot in
            guard let self else { return }
            self.reading = false
            if self.changedWhileReading {
                // Something newer came meanwhile: read that instead.
                self.changedWhileReading = false
                self.lastCount = -1
                return self.tick()
            }
            if case .nothing = snapshot { return }
            for watcher in self.watchers.values { watcher(snapshot) }
        }
    }
}
#endif
